    ob_step0_desc: "Įdiekite gamybinio lygio Oracle 23ai ir APEX aplinką per kelias minutes:",
    ob_step0_p1: "<strong>Kur pasirinkti:</strong> Atidarykite kortelę <strong>Valdymo Skydelis</strong>, kur rasite 12 kuruojamų planų 4 lygiuose (0–4 Pagrindinės DB, 5–7 Tarpinė programinė įranga, 8–9 Kūrimas, 10–11 Nuotoliniai šliuzai).",
    ob_step0_p2: "<strong>Kaip paleisti:</strong> Spustelėkite kortelės mygtuką <code>[ ⚡ Valdymas & Gyvavimo ciklas ]</code> arba paleiskite terminale <code>./scripts/setup-all.sh -b &lt;ID&gt;</code>.",
    ob_step0_p3: "<strong>Rezultatas:</strong> Automatiškai sukonfigūruoja duomenų bazes, APEX, ORDS ir SEPS Wallet be duomenų praradimo ar prievadų konfliktų.",
