    ob_step1_desc: "Patogus ir saugus prisijungimas prie žiniatinklio portalų neatskleidžiant slaptažodžių naršyklės URL:",
    ob_step1_p1: "<strong>Kur rasti:</strong> Atidarykite kortelę <strong>Valdymo Skydelis</strong> – viršuje rodomos aktyvių paslaugų kortelės (APEX, ORDS, Database Actions) su būsenomis.",
    ob_step1_p2: "<strong>Kaip atidaryti:</strong> Spustelėkite <code>[ 🛠️ Atidaryti APEX Darbo Erdvę → ]</code>. Portalas atsidaro naujame skirtuke su iš anksto užpildytu vartotojo vardu.",
    ob_step1_p3: "<strong>Kaip prisijungti:</strong> Slaptažodis automatiškai iššifruojamas į iškarpinę iš SEPS Wallet – slaptažodžio lauke paspauskite <kbd>Ctrl+V</kbd> arba <kbd>Cmd+V</kbd>.",
    ob_step1_p4: "4. Įklijuokite ir prisijunkite:",
