    ob_step2_desc: "Visos duomenų bazės paskyros ir teisės saugiai saugomos šifruotoje Zero-Trust saugykloje (niekada tekste):",
    ob_step2_p1: "<strong>Kur matyti sąsajoje:</strong> Kiekvienos paslaugos kortelės apačioje rodomas vartotojo vardas ir slaptažodžio kopijavimo mygtukas.",
    ob_step2_p2: "<strong>Kaip nukopijuoti:</strong> Paspaudus <code>[ 📋 Kopijuoti Slaptažodį ]</code>, slaptažodis iššifruojamas tiesiai į iškarpinę.",
    ob_step2_p3: "<strong>Kur rasti CLI:</strong> Terminale paleiskite <code>./scripts/get-password.sh &lt;ALIAS&gt; -c</code> slaptažodžiui nukopijuoti be rodymo ekrane (5 taisyklė).",
