    ob_step3_desc: "Prijunkite vietinius kūrėjo įrankius be slaptažodžio naudodami SEPS Wallet ir Raktų pakabuką:",
    ob_step3_p1: "<strong>Kaip nustatyti VS Code:</strong> Terminale paleiskite <code>./scripts/register-connections.sh</code> – jis užregistruoja ryšius tiesiai į VS Code Oracle plėtinį.",
